LayersFunctions.description:
This function is executed right after the 'expression()' calculations.
This function is only available for a Layer with a 'source' of type 'calculate' and that has defined the 'expression()' function.
@param inputs {Array} The value of each input defined in the descriptionHtml. The order of the values is the same as the inputs (i.e. the first input in the descriptionHtml is inputs[0], the second is inputs[1] and so on).

examples:
[
  {
     title: 'Example of afterCalc function',
     color: '#FFA500',
     elements: [
        {
           title: 'This afterCalc function will show a message at the bottom right of the screen',
           name: 'CSR:geologia',
           source: 'calculate',
           visibility: true,
           paramsButtonConfig: [
              {
                 type: 'query',
                 pressed: true
              },
           ],
           descriptionHtml:
              '{{label|text=The afterCalc is run after every expression() execution}}'
              +
              '{{textfield|fieldLabel=Enter your name|id=textInput|labelStyle=text-align:center;}}',
           // The expression function is mandatory to use the afterCalc function.
           expression: function(layerVals, inputs) {
              return undefined;
           },
           afterCalc: function(inputs) {
              let inputValue = inputs[0];
              ExtjsUtils.ALERTIFY.log('Hello ' + inputValue + '!');
           },
        },
     ],
  },
]

