    onClickSum: function(layersValues, inputs, feature) {
        ExtjsUtils.ALERTIFY.log('Sum of layer 0: ' + layersValues[0] + ' (' + layersValues[layersValues.length - 1][0] + ' cells)');
    }
}

functions: {
