    onAreaSummed: function(layersValues, inputs, boundingBox, pixel, lastInfo) {
        ExtjsUtils.ALERTIFY.log('Sum inside ' + boundingBox.join(', ') + ': ' + layersValues[0]);
    }
}

functions: {
