VectorLayer.description:
Replace geometries on this **drawable VectorLayer** with id/attribute control via one options object.
Only available on vector layers from ``VectorFileSource`` (e.g. ``drawable: true``).
Implementation helpers live in {@link DrawableSplit.applyGeomOp}.
@param sourceGeoms {Array.<OpenLayers.Geometry>} Features selected by `feature.geometry` identity.
@param options {Object|function} If a function, treated as ``{ operation: fn }``.
@param options.operation {String|function} ``'difference'`` | ``'intersection'`` | ``'keep'`` or ``function(sourceGeom, sourceFeature) => Geometry[]``.
@param options.with {OpenLayers.Geometry} Operand for difference / intersection.
@param options.attributes {String|function} ``'keep'`` | ``'empty'`` or ``function(sourceAttrs, pieceIndex, pieceCount) => Object``.
@param options.preserveId {Boolean} First piece of each source keeps OpenLayers id/fid.

examples:
// Cut overlaps (difference) — ``layer`` must be a drawable VectorLayer
  layer.applyGeomOp(intersecting, {
    operation: 'difference', with: editedUnion
  });
  // Clip to CAR (intersection)
  layer.applyGeomOp(outsideGeoms, {
    operation: 'intersection', with: carGeometry
  });
  // Custom pieces + empty attrs
  layer.applyGeomOp(geoms, {
    operation: function(g) { return [myTransform(g)]; },
    attributes: 'empty'
  });

VectorLayer.description:
Calls one of the layer's own `functions` by name with the layer as `this`;
falls back to a method of the layer with that name. Extra arguments are
passed through to the function.
@param name {String} Key of the `functions` object (or a layer method name).
@param anyArguments {*} Arguments forwarded to the function.

examples:
{...
  functions: {
    FUNCTION_NAME: function(parameter1) {
      var layer = this;
      console.log(this, parameter1);
    }
  },
  beforeCalc: function () {
    this.callFunction('FUNCTION_NAME', 'parameter1');
  }
}

cluster: {
  distance: function() {
    return this.layer.map.getZoom() > 14 ? 40 : 80;
  },
  clusterKey: function(feature) {
    var zoom = this.layer.map.getZoom();
    if (zoom <= 10) return feature.attributes.regiao;
    if (zoom <= 14) return feature.attributes.bairro;
    return null; // distance only
  },
  clusterGeometry: function(cluster) {
    var key = cluster.attributes.clusterKey;
    var zoom = this.layer.map.getZoom();
    if (zoom <= 10 && REGION_GEOMS[key]) return REGION_GEOMS[key];
    if (zoom <= 14 && BAIRRO_GEOMS[key]) return BAIRRO_GEOMS[key];
    return this.defaultClusterGeometry(cluster); // hull / point
  },
  minClusterPolygonPx: 28
}

[{
  name: "CSR:file_draw", source: "file", type: "empty",
  drawable: {
    maxGeomCount: 5,
    drawModes: ['polygon', 'line'],
    onOverlap: ['merge', 'cut', 'keep'],
    onDrawingStatusChange: function(detail) { console.log(detail.status); },
    onEditToggle: function(active, detail) { console.log(active, detail.reason); }
  }
}]

layer.fillGeometryLayer({
    url: 'https://maps.csr.ufmg.br/theme/app/data/conab/limite_macroregioes.geojson',
    type: 'load',
    loadData: function(inputs, config) {
        var layer = this;
        function featFilterCb(feat){
            return ['31', '35'].indexOf(feat.properties.geocodigo.toString().substring(0, 2)) !== -1;
        }
        layer.events.triggerEvent('startLoadingLayer');
        ExtjsUtils.REQUEST.get(config.url, function(resp) {
            var jsonObjects = JSON.parse(resp.responseText);
            jsonObjects.features = jsonObjects.features.filter(featFilterCb);
            layer.addFeatures(layer.convertGeojson2Features(jsonObjects));
            layer.events.triggerEvent('endLoadingLayer');
        }, function() {
            layer.events.triggerEvent('endLoadingLayer');
        }, false, layer);
    }
})

